                              FArray2D<std::complex<double>>& za,
                              FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
  };
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1,i2)*zb(i2,i3);
  };
  auto zba = [&za, &zb](int i1, int i2, int i3) {
    return zb(i1,i2)*za(i2,i3);
  };

  double delta12 = s(j1,j2) - s(j5,j6) - s(j3,j4);
  double delta56 = s(j5,j6) - s(j1,j2) - s(j3,j4);
  double Delta3 = std::pow(s(j1,j2),2) + std::pow(s(j3,j4),2) + std::pow(s(j5,j6),2)
      - 2*s(j1,j2)*s(j3,j4) - 2*s(j3,j4)*s(j5,j6) - 2*s(j5,j6)*s(j1,j2);

  std::complex<double> M3abit1_value =
      0.5*zb(j2,j4)/(zb(j2,j3)*s(j3,j4)*zab2(j1,j3,j4,j2))
      *(6.0*s(j1,j2)*s(j3,j4)/std::pow(Delta3,2)
        *(t(j1,j3,j4)-t(j2,j3,j4))*zab2(j3,j1,j2,j4)*zab2(j5,j1,j2,j6)

        +za(j1,j2)*delta12/(zb(j5,j6)*Delta3)
        *(zab2(j3,j1,j2,j6)*zb(j1,j4)*zb(j2,j6)
          +zab2(j3,j2,j4,j6)*zb(j1,j2)*zb(j4,j6)
          -za(j1,j3)*zb(j2,j4)*(std::pow(zb(j1,j6),2)
          +std::pow(zb(j2,j6),2)*zab2(j2,j3,j4,j1)/zab2(j1,j3,j4,j2)))

        +zb(j1,j2)*delta12/(za(j5,j6)*Delta3)
        *(zab(j5,j2,j4)*(za(j1,j2)*za(j3,j5)-za(j2,j3)*za(j1,j5))
          -za(j1,j5)*za(j2,j5)*zab2(j3,j1,j2,j4)
          +std::pow(za(j1,j5),2)*za(j1,j3)*zb(j2,j4)*zab2(j2,j3,j4,j1)
          /zab2(j1,j3,j4,j2))

        -2.0*za(j1,j2)*za(j3,j5)/Delta3
        *(zb(j1,j6)*zb(j2,j4)+zb(j1,j4)*zb(j2,j6))*delta56
        -(za(j3,j4)*std::pow(zb(j4,j6),2)/zb(j5,j6)
          +std::pow(za(j3,j5),2)*zb(j3,j4)/za(j5,j6))*s(j1,j2)*t(j2,j3,j4)/Delta3

        +zab(j3,j2,j6)*zb(j4,j6)/zb(j5,j6)

        -za(j1,j3)*zb(j2,j4)/zab2(j1,j3,j4,j2)
        *(zab(j5,j1,j2)*za(j2,j5)/za(j5,j6)
          +zba(j6,j1,j2)*zb(j2,j6)/zb(j5,j6)));

  return M3abit1_value; // @coverage-probe
}

extern "C" {
  std::complex<double> M3abit1_wrapper(int j1, int j2, int j3, int j4, int j5, int j6,
                                        std::complex<double>* fza,
                                        std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return M3abit1(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
